import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = readTwoInts(scanner);
        int n = input[0];
        int m = input[1];
        System.out.println(calculate(n, m));
        scanner.close();
    }

    private static int[] readTwoInts(Scanner scanner) {
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        return new int[]{a, b};
    }

    private static int egcdVariant(int a, int b) {
        int rA = a, rB = b;
        int sA = 1, sB = 0;
        int tA = 0, tB = 1;
        while (rB != 0) {
            int q = rA / rB;
            int tempR = rA;
            rA = rB;
            rB = tempR - q * rB;

            int tempS = sA;
            sA = sB;
            sB = tempS - q * sB;

            int tempT = tA;
            tA = tB;
            tB = tempT - q * tB;
        }
        return rA;
    }

    private static int[] computeCoeffs(int n, int M) {
        int[] C = new int[n + 1];
        C[n] = 1;
        for (int k = n - 1; k >= 0; k--) {
            C[k] = (int)((long)C[k + 1] * (k + 1) % M);
            if (C[k] == 0) {
                break;
            }
        }
        return C;
    }

    private static int calculate(int n, int M) {
        // Initialize K as a list of layers
        java.util.List<java.util.List<int[]>> K = new java.util.ArrayList<>();
        // First layer
        java.util.List<int[]> firstLayer = new java.util.ArrayList<>();
        firstLayer.add(new int[]{1});
        K.add(firstLayer);

        for (int i = 0; i < n - 1; i++) {
            java.util.List<int[]> prevLayer = K.get(i);
            int sizePrev = prevLayer.size();
            int[][] newLayer = new int[sizePrev + i + 1][i + 2];

            // Initialize newLayer with zeros
            for (int j = 0; j < newLayer.length; j++) {
                for (int k = 0; k < newLayer[0].length; k++) {
                    newLayer[j][k] = 0;
                }
            }

            for (int j = 0; j < sizePrev; j++) {
                int[] row = prevLayer.get(j);
                int rowLength = row.length;
                for (int k = 0; k < rowLength; k++) {
                    int val = row[k];
                    for (int h = 0; h <= i; h++) {
                        newLayer[j + h][k] = (int)((newLayer[j + h][k] + (long)val) % M);
                    }
                    newLayer[j + i + 1][i + 1] = (int)((newLayer[j + i + 1][i + 1] + (long)val) % M);
                }
            }
            // Convert newLayer to List<int[]>
            java.util.List<int[]> newLayerList = new java.util.ArrayList<>();
            for (int[] row : newLayer) {
                newLayerList.add(row);
            }
            K.add(newLayerList);
        }

        int[] C = computeCoeffs(n, M);
        int total = 0;

        for (int i = 1; i < n; i++) {
            java.util.List<int[]> layer = K.get(i);
            int ni = layer.size();
            int mi = layer.get(0).length;

            // Create S as a copy of layer
            int[][] S = new int[ni][mi];
            for (int j = 0; j < ni; j++) {
                System.arraycopy(layer.get(j), 0, S[j], 0, mi);
            }

            // S[j][k] = S[j][k] + S[j][k+1] for k in reverse
            for (int j = 0; j < ni; j++) {
                for (int k = mi - 2; k >= 0; k--) {
                    S[j][k] = (S[j][k] + S[j][k + 1]) % M;
                }
            }

            // For j in 1..ni-1, S[j][k] += S[j-1][k]
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    S[j][k] = (S[j][k] + S[j - 1][k]) % M;
                }
            }

            long sum_i = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    long product = ((long)layer.get(j)[k] * S[j - 1][k + 1]) % M;
                    sum_i = (sum_i + product) % M;
                }
            }

            int c = C[i + 1];
            sum_i = (sum_i * c) % M;
            total = (int)((total + sum_i) % M);
        }
        return total;
    }
}
